SELECT     REPORT_DATE                                          AS \"Report Date\",     PO_NUMBER                                            AS \"PO Number\",     PO_STATUS                                            AS \"PO Status Code\",     CASE PO_STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE PO_STATUS     END                                                   AS \"PO Status Description\",     ORDER_TYPE                                           AS \"Order Type\",     WRITTEN_DATE                                         AS \"PO Written Date\",     ORIG_APPROVAL_DATE                                   AS \"Original Approval Date\",     NOT_BEFORE_DATE                                      AS \"Not Before Date\",     NOT_AFTER_DATE                                       AS \"Not After Date\",     DAYS_OUTSTANDING                                     AS \"Days Outstanding\",     CASE         WHEN DAYS_OUTSTANDING &gt; 30 THEN 'OVERDUE - Over 30 Days'         WHEN DAYS_OUTSTANDING &gt; 7  THEN 'REVIEW - 7 to 30 Days'         ELSE 'RECENT - Under 7 Days'     END                                                   AS \"Aging Flag\",     SUPPLIER_ID                                          AS \"Supplier ID\",     SUPPLIER_NAME                                        AS \"Supplier Name\",     SUPPLIER_STATUS                                      AS \"Supplier Status\",     ITEM_ID                                              AS \"Item ID\",     ITEM_DESCRIPTION                                     AS \"Item Description\",     DEPT_NO                                              AS \"Department Number\",     DEPT_NAME                                            AS \"Department Name\",     CLASS_NO                                             AS \"Class Number\",     CLASS_NAME                                           AS \"Class Name\",     SUBCLASS_NO                                          AS \"Subclass Number\",     SUBCLASS_NAME                                        AS \"Subclass Name\",     LOCATION_ID                                          AS \"Location ID\",     LOC_TYPE                                             AS \"Location Type\",     CASE LOC_TYPE         WHEN 'S' THEN STORE_NAME         WHEN 'W' THEN WH_NAME         ELSE TO_CHAR(LOCATION_ID)     END                                                   AS \"Location Name\",     QTY_ORDERED                                          AS \"Quantity Ordered\",     QTY_RECEIVED                                         AS \"Quantity Received\",     QTY_ORDERED - QTY_RECEIVED                           AS \"Quantity Outstanding\",     UNIT_COST                                            AS \"Unit Cost\",     ROUND(OUTSTANDING_COST_RAW, 2)                        AS \"Outstanding Cost\",     ORIGIN_COUNTRY_ID                                    AS \"Origin Country ID\",     VPN                                                   AS \"Vendor Product Number\",     ITEM_LOC_STATUS                                      AS \"Item Location Status\",     CASE ITEM_LOC_STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'         ELSE 'NOT RANGED'     END                                                   AS \"Item Location Status Description\",     RANGED_IND                                           AS \"Ranged Indicator\",     CASE RANGED_IND         WHEN 'Y' THEN 'Deliberately Ranged'         WHEN 'N' THEN 'Incidentally Ranged'         ELSE 'NOT RANGED'     END                                                   AS \"Ranged Indicator Description\",     STUCK_REASON_CODE                                    AS \"Stuck Reason Code\",     CASE STUCK_REASON_CODE         WHEN 'NOT_RANGED' THEN 'NOT RANGED - No item/location record in ITEM_LOC'         WHEN 'DELETE'     THEN 'DELETE STATUS - Purchasing not allowed at Delete status'         WHEN 'INACTIVE'   THEN 'INACTIVE STATUS - Purchasing not allowed at Inactive status'         WHEN 'INCIDENTAL' THEN 'INCIDENTALLY RANGED - RANGED_IND=N; review if deliberate'         ELSE 'REVIEW REQUIRED'     END                                                   AS \"Stuck Reason Description\",     CASE STUCK_REASON_CODE         WHEN 'NOT_RANGED' THEN '1 - HIGH: PO cannot progress without ranging'         WHEN 'DELETE'     THEN '2 - HIGH: PO blocked by Delete status'         WHEN 'INACTIVE'   THEN '3 - MEDIUM: Reactivate or re-range item to location'         WHEN 'INCIDENTAL' THEN '4 - LOW: Confirm if ranging was intentional'         ELSE '5 - REVIEW'     END                                                   AS SEVERITY,     CASE STUCK_REASON_CODE         WHEN 'NOT_RANGED'         THEN 'Range item to location in Active status; confirm with Buying team'         WHEN 'DELETE'         THEN 'Cannot range back from Delete; cancel PO line and re-range to new location'         WHEN 'INACTIVE'         THEN 'Update ITEM_LOC.STATUS to Active or Discontinued to allow purchasing'         WHEN 'INCIDENTAL'         THEN 'Confirm item intended at this location; update RANGED_IND=Y or discontinue'         ELSE 'Review item/location setup in RMS and liaise with Inventory Control'     END                                                  AS \"Recommended Action\",     CURRENT_SOH AS \"Current Stock on Hand\",     CASE         WHEN CURRENT_SOH = 0 AND STUCK_REASON_CODE = 'NOT_RANGED'         THEN 'CRITICAL - OOS and not ranged'         WHEN CURRENT_SOH = 0         THEN 'OUT OF STOCK'         ELSE 'SOH EXISTS'     END                                                 AS \"Stock Urgency\",     COMMENTS FROM (

