tion\":false},{\"prepColumnName\":\"Supplier ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supplier Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supplier Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Item ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"Item Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"Department Number\",\"isUserCalculation\":false},{\"prepColumnName\":\"Department Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Class Number\",\"isUserCalculation\":false},{\"prepColumnName\":\"Class Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Subclass Number\",\"isUserCalculation\":false},{\"prepColumnName\":\"Subclass Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Location ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"Location Type\",\"isUserCalculation\":false},{\"prepColumnName\":\"Location Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Quantity Ordered\",\"isUserCalculation\":false},{\"prepColumnName\":\"Quantity Received\",\"isUserCalculation\":false},{\"prepColumnName\":\"Quantity Outstanding\",\"isUserCalculation\":false},{\"prepColumnName\":\"Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Outstanding Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Origin Country ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"Vendor Product Number\",\"isUserCalculation\":false},{\"prepColumnName\":\"Item Location Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Item Location Status Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ranged Indicator\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ranged Indicator Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stuck Reason Code\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stuck Reason Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"SEVERITY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false},{\"prepColumnName\":\"Current Stock on Hand\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stock Urgency\",\"isUserCalculation\":false},{\"prepColumnName\":\"COMMENTS\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO Number\"],\"expressionSourceColumns\":[\"PO Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Department Number\"],\"expressionSourceColumns\":[\"Department Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Department Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Department Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class Number\"],\"expressionSourceColumns\":[\"Class Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass Number\"],\"expressionSourceColumns\":[\"Subclass Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT\\n    REPORT_DATE                                          AS \\\"Report Date\\\",\\n    PO_NUMBER                                            AS \\\"PO Number\\\",\\n    PO_STATUS                                            AS \\\"PO Status Code\\\",\\n    CASE PO_STATUS\\n        WHEN 'W' THEN 'Worksheet'\\n        WHEN 'S' THEN 'Submitted'\\n        WHEN 'A' THEN 'Approved'\\n        WHEN 'C' THEN 'Closed'\\n        ELSE PO_STATUS\\n    END                                                   AS \\\"PO Status Description\\\",\\n    ORDER_TYPE                                           AS \\\"Order Type\\\",\\n    WRITTEN_DATE                                         AS \\\"PO Written Date\\\",\\n    ORIG_APPROVAL_DATE                                   AS \\\"Original Approval Date\\\",\\n    NOT_BEFORE_DATE                                      AS \\\"Not Before Date\\\",\\n    NOT_AFTER_DATE                                       AS \\\"Not After Date\\\",\\n    DAYS_OUTSTANDING                                     AS \\\"Days Outstanding\\\",\\n    CASE\\n        WHEN DAYS_OUTSTANDING &gt; 30 THEN 'OVERDUE - Over 30 Days'\\n        WHEN DAYS_OUTSTANDING &gt; 7  THEN 'REVIEW - 7 to 30 Days'\\n        ELSE 'RECENT - Under 7 Days'\\n    END                                                   AS \\\"Aging Flag\\\",\\n    SUPPLIER_ID                                          AS \\\"Supplier ID\\\",\\n    SUPPLIER_NAME                                        AS \\\"Supplier Name\\\",\\n    SUPPLIER_STATUS                                      AS \\\"Supplier Status\\\",\\n    ITEM_ID                                              AS \\\"Item ID\\\",\\n    ITEM_DESCRIPTION                                     AS \\\"Item Description\\\",\\n    DEPT_NO                                              AS \\\"Department Number\\\",\\n    DEPT_NAME                                            AS \\\"Department Name\\\",\\n    CLASS_NO                                             AS \\\"Class Number\\\",\\n    CLASS_NAME                                           AS \\\"Class Name\\\",\\n    SUBCLASS_NO                                          AS \\\"Subclass Number\\\",\\n    SUBCLASS_NAME                                        AS \\\"Subclass Name\\\",\\n    LOCATION_ID                                          AS \\\"Location ID\\\",\\n    LOC_TYPE                                             AS \\\"Location Type\\\",\\n    CASE LOC_TYPE\\n        WHEN 'S' THEN STORE_NAME\\n        WHEN 'W' THEN WH_NAME\\n        ELSE TO_CHAR(LOCATION_ID)\\n    END                                                   AS \\\"Location Name\\\",\\n    QTY_ORDERED                                          AS \\\"Quantity Ordered\\\",\\n    QTY_RECEIVED                                         AS \\\"Quantity Received\\\",\\n    QTY_ORDERED - QTY_RECEIVED                           AS \\\"Quantity Outstanding\\\",\\n    UNIT_COST                                            AS \\\"Unit Cost\\\",\\n    ROUND(OUTSTANDING_COST_RAW, 2)                        AS \\\"Outstanding Cost\\\",\\n    ORIGIN_COUNTRY_ID                                    AS \\\"Origin Country ID\\\",\\n    VPN                                                   AS \\\"Vendor Product Number\\\",\\n    ITEM_LOC_STATUS                                      AS \\\"Item Location Status\\\",\\n    CASE ITEM_LOC_STATUS\\n        WHEN 'A' THEN 'Active'\\n        WHEN 'C' THEN 'Discontinued'\\n        WHEN 'I' THEN 'Inactive'\\n        WHEN 'D' THEN 'Delete'\\n        ELSE 'NOT RANGED'\\n    END                                                   AS \\\"Item Location Status Description\\\",\\n    RANGED_IND                                           AS \\\"Ranged Indicator\\\",\\n    CASE RANGED_IND\\n        WHEN 'Y' THEN 'Deliberately Ranged'\\n        WHEN 'N' THEN 'Incidentally Ranged'\\n        ELSE 'NOT RANGED'\\n    END                                                   AS \\\"Ranged Indicator Description\\\",\\n    STUCK_REASON_CODE                                    AS \\\"Stuck Reason Code\\\",\\n    CASE STUCK_REASON_CODE\\n        WHEN 'NOT_RANGED' THEN 'NOT RANGED - No item/location record in ITEM_LOC'\\n        WHEN 'DELETE'     THEN 'DELETE STATUS - Purchasing not allowed at Delete status'\\n        WHEN 'INACTIVE'   THEN 'INACTIVE STATUS - Purchasing not allowed at Inactive status'\\n        WHEN 'INCIDENTAL' THEN 'INCIDENTALLY RANGED - RANGED_IND=N; review if deliberate'\\n        ELSE 'REVIEW REQUIRED'\\n    END                                                   AS \\\"Stuck Reason Description\\\",\\n    CASE STUCK_REASON_CODE\\n        WHEN 'NOT_RANGED' THEN '1 - HIGH: PO cannot progress without ranging'\\n        WHEN 'DELETE'     THEN '2 - HIGH: PO blocked by Delete status'\\n        WHEN 'INACTIVE'   THEN '3 - MEDIUM: Reactivate or re-range item to location'\\n        WHEN 'INCIDENTAL' THEN '4 - LOW: Confirm if ranging was intentional'\\n        ELSE '5 - REVIEW'\\n    END                                                   AS SEVERITY,\\n    CASE STUCK_REASON_CODE\\n        WHEN 'NOT_RANGED'\\n        THEN 'Range item to location in Active status; confirm with Buying team'\\n        WHEN 'DELETE'\\n        THEN 'Cannot range back from Delete; cancel PO line and re-range to new location'\\n        WHEN 'INACTIVE'\\n        THEN 'Update ITEM_LOC.STATUS to Active or Discontinued to allow purchasing'\\n        WHEN 'INCIDENTAL'\\n        THEN 'Confirm item intended at this location; update RANGED_IND=Y or discontinue'\\n        ELSE 'Review item/location setup in RMS and liaise with Inventory Control'\\n    END                                                  AS \\\"Recommended Action\\\",\\n    CURRENT_SOH AS \\\"Current Stock on Hand\\\",\\n    CASE\\n        WHEN CURRENT_SOH = 0 AND STUCK_REASON_CODE = 'NOT_RANGED'\\n        THEN 'CRITICAL - OOS and not ranged'\\n        WHEN CURRENT_SOH = 0\\n        THEN 'OUT OF STOCK'\\n        ELSE 'SOH EXISTS'\\n    END                                                 AS \\\"Stock Urgency\\\",\\n    COMMENTS\\nFROM (\\n

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        oh.ORDER_NO                                       AS PO_NUMBER,\\n        oh.STATUS                                         AS PO_STATUS,\\n        oh.ORDER_TYPE                                     AS ORDER_TYPE,\\n        oh.WRITTEN_DATE                                   AS WRITTEN_DATE,\\n        oh.ORIG_APPROVAL_DATE                             AS ORIG_APPROVAL_DATE,\\n        oh.NOT_BEFORE_DATE                                AS NOT_BEFORE_DATE,\\n        oh.NOT_AFTER_DATE                                 AS NOT_AFTER_DATE,\\n        TRUNC(SYSDATE) - TRUNC(oh.WRITTEN_DATE)          AS DAYS_OUTSTANDING,\\n        oh.SUPPLIER                                       AS SUPPLIER_ID,\\n        sp.SUP_NAME                                       AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                     AS SUPPLIER_STATUS,\\n        ol.ITEM                                           AS ITEM_ID,\\n        im.ITEM_DESC                                      AS ITEM_DESCRIPTION,\\n        im.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        im.CLASS                                          AS CLASS_NO,\\n        c.CLASS_NAME                                      AS CLASS_NAME,\\n        im.SUBCLASS                                       AS SUBCLASS_NO,\\n        sc.SUB_NAME                                       AS SUBCLASS_NAME,\\n        ol.LOCATION                                       AS LOCATION_ID,\\n        ol.LOC_TYPE                                       AS LOC_TYPE,\\n        st.STORE_NAME                                     AS STORE_NAME,\\n        wh.WH_NAME                                        AS WH_NAME,\\n        NVL(ol.QTY_ORDERED,  0)                           AS QTY_ORDERED,\\n        NVL(ol.QTY_RECEIVED, 0)                           AS QTY_RECEIVED,\\n        ol.UNIT_COST                                      AS UNIT_COST,\\n        (NVL(ol.QTY_ORDERED, 0)\\n         - NVL(ol.QTY_RECEIVED, 0)) * NVL(ol.UNIT_COST, 0)\\n                                                          AS OUTSTANDING_COST_RAW,\\n        os.ORIGIN_COUNTRY_ID                              AS ORIGIN_COUNTRY_ID,\\n        os.REF_ITEM                                       AS VPN,\\n        il.STATUS                                         AS ITEM_LOC_STATUS,\\n        il.RANGED_IND                                     AS RANGED_IND,\\n        CASE\\n            WHEN il.ITEM       IS NULL THEN 'NOT_RANGED'\\n            WHEN il.STATUS     = 'D'   THEN 'DELETE'\\n            WHEN il.STATUS     = 'I'   THEN 'INACTIVE'\\n            WHEN il.RANGED_IND = 'N'\\n                 AND il.STATUS NOT IN ('D','I') THEN 'INCIDENTAL'\\n            ELSE 'OTHER'\\n        END                                               AS STUCK_REASON_CODE,\\n        NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH,\\n        oh.COMMENT_DESC                                   AS COMMENTS\\n    FROM  MFCS_RDS.RDS_WV_ORDHEAD              oh\\n    JOIN  MFCS_RDS.RDS_WV_ORDLOC               ol   ON  oh.ORDER_NO  = ol.ORDER_NO\\n    JOIN (\\n

-- ── Query 6 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS, STATUS\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                          im   ON  ol.ITEM      = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  im.DEPT      = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c    ON  im.DEPT      = c.DEPT\\n                                                    AND  im.CLASS     = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc   ON  im.DEPT      = sc.DEPT\\n                                                    AND  im.CLASS     = sc.CLASS\\n                                                    AND  im.SUBCLASS  = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  ol.ORDER_NO  = os.ORDER_NO\\n                                                    AND  ol.ITEM      = os.ITEM\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp   ON  oh.SUPPLIER  = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st   ON  ol.LOCATION  = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH               wh   ON  ol.LOCATION  = wh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC         il   ON  ol.ITEM      = il.ITEM\\n                                                    AND  ol.LOCATION  = il.LOC\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ol.ITEM      = ils.ITEM\\n                                                    AND  ol.LOCATION  = ils.LOC\\n                                                    AND  ol.LOC_TYPE  = ils.LOC_TYPE\\n    WHERE\\n        oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n        AND (\\n            il.ITEM       IS NULL\\n            OR il.STATUS  = 'D'\\n            OR il.STATUS  = 'I'\\n            OR il.RANGED_IND = 'N'\\n        )\\n)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","